12	const SOURCES = ["INTERNAL", "GOOGLE", "TRUSTPILOT", "HOSTADVICE"] as const;
13	
14	const schema = z.object({
15	  id: z.string().optional(),
16	  author: z.string().min(1, "Author name is required.").max(80),
17	  role: z.string().max(120).optional(),
18	  body: z.string().min(1, "Review text is required.").max(2000),
19	  rating: z.coerce.number().int().min(1).max(5).default(5),
20	  source: z.enum(SOURCES).default("INTERNAL"),
21	  approved: z.boolean(),
22	  featured: z.boolean(),
23	});
