export async function Testimonials() {
  const testimonials = await db.testimonial
    .findMany({
      where: { published: true },
      orderBy: { sortOrder: "asc" },
    })
    .catch(() => []);

  // Real social proof: render published testimonials the admin has entered.
  if (testimonials.length > 0) {
    const items: ReviewCarouselItem[] = testimonials.map((t) => ({
      id: t.id,
      quote: t.quote,
      name: t.author,
      meta: t.role ?? "",
      avatar: t.avatarEmoji ?? "💬",
      rating: t.rating,
    }));
    return <ReviewCarousel items={items} />;
  }

  // Fallback: honest illustrative use-cases, clearly disclaimed.
  const items: ReviewCarouselItem[] = USE_CASES.map((u) => ({
    id: u.role,
    quote: u.quote,
    name: u.role,
    meta: u.context,
    avatar: u.initial,
  }));

  return (
    <div>
      <ReviewCarousel items={items} />
      <p className="mt-6 text-center text-xs text-slate-600">
        Illustrative use-cases showing what you can run on Nxeon — not testimonials from named
        customers.
      </p>
    </div>
  );
}
