import { db } from "@/lib/db";
import { ReviewCarousel, type ReviewCarouselItem } from "./ReviewCarousel";

/**
 * "What our customers say" — real, approved reviews from the Reviews engine
 * (/admin/reviews), featured ones first. Renders NOTHING when there are no
 * approved reviews yet, so the homepage never shows an empty or fabricated
 * section pre-launch (the illustrative <Testimonials/> block covers that state).
 *
 * Renders as a one-at-a-time auto-sliding <ReviewCarousel/> rather than the
 * full grid of up to 6 cards this used to be — condenses this section (per
 * board request).
 */

const SOURCE_LABEL: Record<string, string> = {
  INTERNAL: "Verified customer",
  GOOGLE: "via Google",
  TRUSTPILOT: "via Trustpilot",
  HOSTADVICE: "via HostAdvice",
};

export async function CustomerReviews() {
  const reviews = await db.review
    .findMany({
      where: { approved: true },
      orderBy: [{ featured: "desc" }, { createdAt: "desc" }],
      take: 6,
    })
    .catch(() => []);

  if (reviews.length === 0) return null;

  const items: ReviewCarouselItem[] = reviews.map((r) => ({
    id: r.id,
    quote: r.body,
    name: r.author,
    meta: `${r.role ? `${r.role} · ` : ""}${SOURCE_LABEL[r.source] ?? "Verified customer"}`,
    avatar: r.author.charAt(0).toUpperCase(),
    rating: r.rating,
  }));

  return <ReviewCarousel items={items} />;
}
