import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import {
  readFileBuffer,
  writeFileBuffer,
  mkdirPath,
  normalizePath,
  validateName,
  joinPath,
  type SftpServer,
} from "@/lib/sftp";

/**
 * File download / upload endpoint for the in-portal file manager.
 *
 *   GET  /api/files/[serverId]?path=/abs/file&download=1   -> streams the file
 *   POST /api/files/[serverId]?path=/abs/dir               -> multipart upload
 *
 * Both are authenticated and ownership-checked (owner or admin), path-validated
 * (absolute, no `..`), size-capped, and rate-limited. Real SFTP in production;
 * an in-memory simulation on the sandbox (handled inside lib/sftp).
 */
export const dynamic = "force-dynamic";

/** Max upload size accepted per request. */
const MAX_UPLOAD_BYTES = 250 * 1024 * 1024; // 250 MB

async function ownedServer(
  serverId: string,
  userId: string,
  isAdmin: boolean
): Promise<SftpServer | null> {
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true,
      userId: true,
      rootPassword: true,
      // The encrypted-at-rest password is the authoritative one for any server
      // provisioned after credential encryption shipped; the plaintext column is
      // null for those. serverRootPassword() prefers Enc and falls back to
      // plaintext, so BOTH must be selected — omitting Enc made every
      // encrypted-password server fail with "Server has no root password set."
      rootPasswordEnc: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
      node: { select: { publicIp: true } },
    },

  @@index([createdAt])
  @@index([serverId, createdAt])
  @@index([nodeKind, createdAt])
}

model Improvement {
  id           String   @id @default(cuid())
  batchId      String? // groups one nightly scan
  category     String // bug | feature | error | enhancement | security | performance
  severity     String   @default("medium") // low | medium | high | critical
  title        String
  summary      String // one-to-two sentence concise description (owner reads this)
  detail       String? // longer optional detail, collapsed by default
  source       String? // nightly-scan | feedback | error-log | bug-report | audit
  effort       String? // S | M | L
  filesHint    String? // suggested files/areas to change
  status       String   @default("PROPOSED") // PROPOSED | APPROVED | DECLINED | IN_PROGRESS | DONE
  resolvedNote String?
  ownerNote    String? // owner's instructions for how to handle this item
  createdAt    DateTime @default(now())
  updatedAt    DateTime @updatedAt

  @@index([status])
  @@index([batchId])
}

// ============================================================================
// Website Builder (Wix-style) — additive only. A Site is edited in-browser and
// PUBLISHES INTO an existing Website row (reusing nginx/SSL/domain machinery);
// websiteId is a scalar FK on purpose so this never touches the Website model.
// ============================================================================
model Site {
  id          String        @id @default(cuid())
  userId      String
  name        String
  slug        String // the *.nxeon subdomain label; globally unique
  websiteId   String? // the Website row it publishes into once live
  status      String        @default("DRAFT") // DRAFT | PUBLISHING | PUBLISHED | FAILED
  templateKey String? // starter template it began from
  publishedAt DateTime?
  error       String?
  createdAt   DateTime      @default(now())
  updatedAt   DateTime      @updatedAt
  pages       SitePage[]
  versions    SiteVersion[]
  @@index([kind, createdAt])
}

// Learning loop (admin-approved): draft answers proposed from real questions the
// assistant couldn't handle. On approval the answer becomes part of the KB (it's
// folded into KbChunk, and reindex keeps it) so the assistant improves over time.
model KbSuggestion {
  id        String   @id @default(cuid())
  question  String
  answer    String // proposed FAQ-style answer
  category  String?
  source    String   @default("gap") // gap | conversation
  status    String   @default("pending") // pending | approved | rejected
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([status, createdAt])
}

// ---------------------------------------------------------------------------
// Riddle promotion (/riddle). ONE global first-solver wins a $100 credit.
// ---------------------------------------------------------------------------
model RiddleWinner {
  id         String   @id @default(cuid())
  // Singleton guard: unique + always-true => at most ONE row can ever exist,
  // so the "first correct answer wins" award is atomic even under a race (the
  // second concurrent insert violates the unique index and loses).
  singleton  Boolean  @unique @default(true)
  userId     String
